<?php require_once 'auth.php';require_admin();header('Content-Type: application/json; charset=utf-8');$pdo=db();$productId=(int)($_GET['product_id']??0);if(!$pdo||!$productId){echo json_encode(['sizes'=>[],'rows'=>[],'materials'=>[],'colors'=>[]]);exit;}$q=$pdo->prepare('SELECT id,name,details_json FROM product_size_options WHERE product_id=? ORDER BY sort_order,id');$q->execute([$productId]);$sizes=$q->fetchAll(PDO::FETCH_ASSOC);foreach($sizes as &$size)$size['details']=json_decode($size['details_json']?:'{}',true)?:[];unset($size);$q=$pdo->prepare('SELECT m.id,m.name,m.code,m.coefficient,r.color_ids_json FROM product_variant_materials r JOIN materials m ON m.id=r.material_id WHERE r.product_id=? ORDER BY m.name');$q->execute([$productId]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);foreach($rows as &$row)$row['color_ids']=json_decode($row['color_ids_json']?:'[]',true)?:[];unset($row);$q=$pdo->prepare('SELECT material_id,size_option_id,price FROM product_variant_prices WHERE product_id=?');$q->execute([$productId]);$prices=[];foreach($q->fetchAll(PDO::FETCH_ASSOC) as $p)$prices[$p['material_id'].'_'.$p['size_option_id']]=$p['price'];$materials=$pdo->query('SELECT id,name,code FROM materials ORDER BY name')->fetchAll(PDO::FETCH_ASSOC);$colors=$pdo->query('SELECT id,material_id,code,image,hex_code FROM material_colors ORDER BY code')->fetchAll(PDO::FETCH_ASSOC);$q=$pdo->prepare('SELECT p.price,COALESCE(c.coefficient,1) category_coefficient,COALESCE(co.coefficient,1) collection_coefficient FROM products p LEFT JOIN categories c ON c.id=p.category_id LEFT JOIN collections co ON co.id=p.collection_id WHERE p.id=?');$q->execute([$productId]);$formula=$q->fetch(PDO::FETCH_ASSOC)?:['price'=>0,'category_coefficient'=>1,'collection_coefficient'=>1];echo json_encode(compact('sizes','rows','prices','materials','colors','formula'),JSON_UNESCAPED_UNICODE);
